* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
  background: radial-gradient(1200px 600px at 20% -10%, #1a2333 0%, var(--bg) 60%) no-repeat fixed;
  color: var(--text);
  font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  min-height: 100vh;
  padding: 2rem 1rem;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--focus);
  color: #111;
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  font-weight: 600;
  text-decoration: none;
}
.skip-link:focus { left: 1rem; top: 1rem; outline: 3px solid #fff; }

main {
  max-width: 560px;
  margin: 0 auto;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 2rem;
  box-shadow: 0 10px 30px rgba(0,0,0,0.35);
}

h1 {
  margin: 0 0 0.25rem;
  font-size: 1.5rem;
  letter-spacing: -0.01em;
}

.intro {
  margin: 0 0 1.5rem;
  color: var(--text-muted);
  font-size: 0.925rem;
}

.form-field { margin-bottom: 1.5rem; }

fieldset {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1rem 1.25rem 1.25rem;
  margin: 0;
  background: var(--surface-2);
}

legend {
  padding: 0 0.5rem;
  font-weight: 600;
  color: var(--text);
}

legend span[aria-hidden="true"] { color: var(--danger); margin-left: 0.15rem; }

.help {
  margin: 0.25rem 0 0.875rem;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
  border: 1px solid transparent;
  border-radius: 8px;
  transition: background-color .15s ease, border-color .15s ease;
}
.option + .option { margin-top: 0.25rem; }
.option:hover { background: rgba(110,168,254,0.08); }
.option:has(input:checked) {
  background: rgba(110,168,254,0.12);
  border-color: rgba(110,168,254,0.45);
}

/* Custom radio visuals; keep input focusable & operable */
input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.15rem;
  height: 1.15rem;
  margin: 0;
  border: 2px solid var(--border-strong);
  border-radius: 50%;
  background: #0b0f14;
  display: inline-grid;
  place-content: center;
  cursor: pointer;
  flex: 0 0 auto;
  transition: border-color .15s ease, box-shadow .15s ease;
}
input[type="radio"]::before {
  content: "";
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  background: var(--accent);
  transform: scale(0);
  transition: transform .15s ease;
}
input[type="radio"]:checked {
  border-color: var(--accent);
}
input[type="radio"]:checked::before { transform: scale(1); }

input[type="radio"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

label {
  cursor: pointer;
  user-select: none;
  color: var(--text);
}

.submit {
  appearance: none;
  border: 1px solid var(--accent-strong);
  background: linear-gradient(180deg, var(--accent) 0%, var(--accent-strong) 100%);
  color: #0a1530;
  font: inherit;
  font-weight: 600;
  padding: 0.7rem 1.1rem;
  border-radius: 8px;
  cursor: pointer;
  transition: filter .15s ease, transform .05s ease;
}
.submit:hover { filter: brightness(1.06); }
.submit:active { transform: translateY(1px); }
.submit:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.status {
  margin: 1rem 0 0;
  min-height: 1.25rem;
  font-size: 0.925rem;
}
.status.is-error { color: var(--danger); }
.status.is-success { color: var(--success); }

/* Forced colors / high contrast support */
@media (forced-colors: active) {
  fieldset, .option, main, .submit { border-color: CanvasText; }
  input[type="radio"] { border-color: CanvasText; }
  input[type="radio"]::before { background: Highlight; }
  .submit { background: ButtonFace; color: ButtonText; }
  input[type="radio"]:focus-visible,
  .submit:focus-visible { outline-color: Highlight; }
}
