const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');
const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');

(async () => {
  const html = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf8');
  const css = fs.readFileSync(path.join(__dirname, 'styles.css'), 'utf8');
  const inlined = html.replace(/<link rel="stylesheet" href="styles\.css">/, `<style>${css}</style>`);
  const dom = new JSDOM(inlined, { runScripts: 'dangerously', pretendToBeVisual: true });
  const { window } = dom;
  await new Promise(r => window.addEventListener('load', r));
  window.eval(axeSource);
  const results = await window.axe.run(window.document, {
    resultTypes: ['violations'],
  });
  console.log('Violations:', results.violations.length);
  for (const v of results.violations) {
    console.log('-', v.id, '|', v.impact, '|', v.help);
    for (const n of v.nodes) {
      console.log('   target:', n.target.join(','));
      console.log('   ', (n.failureSummary || '').replace(/\n/g, '\n    '));
    }
  }
  process.exit(results.violations.length ? 1 : 0);
})();

